float sphereIntersectionTime(vec3 rayStart, vec3 rayDir, vec3 center, float radius){
    vec3 pos = rayStart - center;
    float a = dot(rayDir, rayDir);
    float b = 2.f * dot(pos, rayDir);
    float c = dot(pos, pos) - radius * radius;


    float temp = b * b - 4.f * a * c;
    if(temp < 0.f){
        return 1.f / 0.f;//This should be positive infinity
    }

    return (-b - sqrt(temp)) / (2.f * a);
}

bool processWormhole(inout vec3 rayPos, inout vec3 rayDir, vec3 p1, vec3 p2, float outerRadius, float innerRadius, float theta, float phi, bool flipChirality){
    float t1 = sphereIntersectionTime(rayPos, rayDir, p1, outerRadius);
    float t2 = sphereIntersectionTime(rayPos, rayDir, p2, outerRadius);


    if(t1 < 0.f && length(rayPos - p1) < outerRadius){
        t1 = 0.0f;
    }
    if(t2 < 0.f && length(rayPos - p2) < outerRadius){
        t2 = 0.0f;
    }



    if(isinf(t1)){
        t1 = -1.f;
    }

    if(isinf(t2)){
        t2 = -1.f;
    }

    if(t1 >= 0.f && t2 >= 0.f){
        rayPos += rayDir * min(t1, t2);
    }else if(t1 >= 0.f){
        rayPos += rayDir * (t1 + 0.0);
    }else if(t2 >= 0.f){
        rayPos += rayDir * (t2 + 0.0);
    }else{
       return false;
    }


    float flip = flipChirality ? -1.f : 1.f;

    for(int i = 0; i < 10; i++){

        if(!timeStep(rayPos, rayDir, p1, p2, outerRadius, innerRadius, 0.05, theta, phi, flip)){
            break;
        }
    }

    return true;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;


    //Camera Controls
    vec3 camPos = 2.5.f * vec3(cos(iTime), sin(iTime), 0);
    vec3 camDir = -normalize(camPos);

    vec3 right = cross(camDir, vec3(0,0,1));
    right /= length(right);
    vec3 up = cross(right, camDir);
    up /= length(up);


    vec3 rayPos = camPos;
    vec3 rayDir = camDir + 2.f * (right * uv.x + up * uv.y);
    rayDir /= length(rayDir);


    //Wormhole Controls
    vec3 p1 = vec3(0,2,0);
    vec3 p2 = vec3(0,-2,0);
    float outerRadius = 2.0f;
    float innerRadius = 1.f;
    float theta = 0.f;
    float phi = 0.f;
    bool flipChirality = false;
    int maxWormholing = 10;

    //this flips the angle phi on one end of the wormhole
    float flip = -1.f;
    if(flipChirality){
        flip = 1.f;
    }

    for(int i = 0; i < maxWormholing; i++){
        if(!processWormhole(rayPos, rayDir, p1, p2, outerRadius, innerRadius, theta, phi, flipChirality)){
            break;
        }
    }


    vec3 sphere = vec3(4,4,3.f * cos(iTime));
    float sphereRadius = 1.f;
    float hi = sphereIntersectionTime(rayPos.xyz, rayDir.xyz, sphere, sphereRadius);

    if(!isinf(hi) && hi > 0.f){
        fragColor = vec4(normalize((rayPos.xyz + rayDir.xyz * hi) - sphere) * 0.5 + 0.5, 1);
        return;
    }

    // Output to screen


    vec3 temp = abs(rayDir);
    float maxDir = max(temp.x, max(temp.y, temp.z));
    vec3 color = 0.5 * (vec3(equal(vec3(maxDir), temp)) + vec3(equal(vec3(maxDir), rayDir)));

    //color = normalize(rayDir) * 0.5 + 0.5;//Pretty colors

    fragColor = vec4(color, 1);
}
